use ingetrazo_gui::IngeTrazoApp;
fn main(){let mut a=IngeTrazoApp::new();let files:Vec<_>=std::env::args().skip(1).collect();a.import_geographic_paths(std::path::Path::new(&files[0])).unwrap();let first=a.scene.tile_layer.clone();let mut path_counts=vec![a.scene.geo_paths.len()];a.import_geographic_paths(std::path::Path::new(&files[1])).unwrap();let second=a.scene.tile_layer.clone();path_counts.push(a.scene.geo_paths.len());a.undo();let undone=a.scene.tile_layer.clone();path_counts.push(a.scene.geo_paths.len());a.undo();let older_undone=a.scene.tile_layer.clone();path_counts.push(a.scene.geo_paths.len());a.redo();let redone=a.scene.tile_layer.clone();path_counts.push(a.scene.geo_paths.len());println!("{}",serde_json::json!({"path_counts":path_counts,"first":first,"second":second,"undone":undone,"older_undone":older_undone,"redone":redone}));}
